package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.ArbitraryLengthPath;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedCostEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedCostTestSupport;
import org.junit.jupiter.api.Test;

class LmdbPackedCostModelPropertyPathTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SEED = VF.createIRI("urn:test:path-cost:seed");
	private static final IRI STEP = VF.createIRI("urn:test:path-cost:step");

	@Test
	void endpointBoundPathPublishesInclusiveTraversalWork() {
		StatementPattern prefix = new StatementPattern(Var.of("seed"), Var.of("seedPredicate", SEED), Var.of("s"));
		StatementPattern step = new StatementPattern(Var.of("s"), Var.of("stepPredicate", STEP), Var.of("o"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("s"), step, Var.of("o"), 1L);
		PackedCostTestSupport.CostCall call = PackedCostTestSupport.disconnectedFactor(prefix, path, 7.0d);
		PackedCostEstimate estimate = new PackedCostEstimate();

		new LmdbPackedCostModel(storageUnavailableRuntime()).estimate(
				call.query(), call.factorRelationId(), call.context(), estimate);

		assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, estimate.costScope());
		assertTrue(estimate.pathExpansions() >= 7.0d,
				"Every endpoint binding must perform at least one path expansion");
		assertTrue(estimate.randomSeeks() >= estimate.pathExpansions(),
				"Each LMDB path expansion opens an indexed step lookup");
		assertTrue(estimate.iteratorOpens() >= estimate.pathExpansions(),
				"Each LMDB path expansion opens its step iterator");
		assertEquals(estimate.outputRows(), estimate.resultRows(), 0.0d,
				"Path result production must remain independent from traversal work");
		assertTrue(estimate.workRows() > estimate.outputRows(),
				"An endpoint-bound property path costs more than copying its result rows");
	}

	private static LmdbEstimatorRuntime storageUnavailableRuntime() {
		return new LmdbEstimatorRuntime(null, null, null, null, null, null, null);
	}
}
